For now, here's a quick **Node.js/Express example** with Redis (or in-memory fallback):

```javascript
const express = require('express');
const NodeCache = require('node-cache');

const app = express();
const cache = new NodeCache({ stdTTL: 300 }); // 5-minute TTL

// Middleware to check cache
const cacheMiddleware = (key) => (req, res, next) => {
  const cached = cache.get(key);
  if (cached) {
    return res.json(cached);
  }
  next();
};

// Fetch user profile from DB/service
async function fetchUserProfile(userId) {
  // Your DB query here
  return { id: userId, name: 'John', email: 'john@example.com' };
}

// API endpoint with cache
app.get('/api/users/:id', cacheMiddleware(`user`), async (req, res) => {
  const { id } = req.params;
  const profile = await fetchUserProfile(id);
  cache.set(`user:${id}`, profile);
  res.json(profile);
});

app.listen(3000);
```

